{
  "purpose": "Emisar lets operators and MCP-capable AI agents run declared infrastructure actions through policy, approvals, and an audit trail. This repository contains the Phoenix control plane, an outbound-only Go host runner, the MCP bridge and CLI, action packs, customer integrations, and production infrastructure.",
  "components": [
    {
      "path": "portal",
      "what_it_does": "Elixir/Phoenix umbrella containing the control plane, operator console, public website, and remote MCP API."
    },
    {
      "path": "portal/apps/emisar",
      "what_it_does": "Domain contexts, authorization, Ecto persistence, recurrent jobs, and the bundled pack catalog."
    },
    {
      "path": "portal/apps/emisar_web",
      "what_it_does": "HTTP controllers, LiveView screens, runner WebSocket, MCP/OAuth endpoints, and marketing pages."
    },
    {
      "path": "portal/config",
      "what_it_does": "Compile-time and runtime application configuration."
    },
    {
      "path": "portal/rel",
      "what_it_does": "Release commands and overlays used to migrate and start the deployed application."
    },
    {
      "path": "runner",
      "what_it_does": "Go host daemon and operator CLI that validate, execute, redact, and journal infrastructure actions."
    },
    {
      "path": "runner/internal",
      "what_it_does": "Runner transport, execution engine, pack loading, argument validation, admission, redaction, and audit implementations."
    },
    {
      "path": "runner/pkg/actionspec",
      "what_it_does": "Shared action descriptor types that define the action schema."
    },
    {
      "path": "runner/pkg/packspec",
      "what_it_does": "Shared pack manifest types."
    },
    {
      "path": "runner/cmd/packctl",
      "what_it_does": "Registry builder and publisher using the runner's exact pack loader and content hashing."
    },
    {
      "path": "mcp",
      "what_it_does": "Standard-library-only Go MCP bridge and direct CLI, including client setup, credentials, and signed dispatch."
    },
    {
      "path": "packs",
      "what_it_does": "Versioned YAML action packs with scripts, service fixtures, and semantic behavior tests."
    },
    {
      "path": "infra",
      "what_it_does": "Terraform production stack for Google Cloud networking, compute, database, IAM, secrets, DNS, and monitoring."
    },
    {
      "path": "skills",
      "what_it_does": "Public customer skills for installation, client connection, pack authoring, and incident response."
    },
    {
      "path": "dist",
      "what_it_does": "Tracked integration packages alongside ignored generated distribution artifacts."
    },
    {
      "path": "dev",
      "what_it_does": "Development container images, service configurations, demo fixtures, and integration-test harnesses."
    },
    {
      "path": "docker-compose.yml",
      "what_it_does": "Packaged local topology with Portal, demo data, runners, MCP, and signing services."
    },
    {
      "path": "run",
      "what_it_does": "Root contributor entry point that bootstraps and invokes the Go development tooling."
    },
    {
      "path": "tools",
      "what_it_does": "Separate Go module for contributor commands, CI, browser tooling, tests, and release operations."
    },
    {
      "path": ".tool-versions",
      "what_it_does": "Exact Erlang, Elixir, Go, Terraform, and TFLint versions for development and CI."
    },
    {
      "path": ".github/workflows",
      "what_it_does": "Validation, Portal delivery, component releases, pack behavior tests, and MCP certification workflows."
    },
    {
      "path": ".agent/kb",
      "what_it_does": "Repository architecture, interface contracts, engineering rules, and operational runbooks."
    }
  ],
  "build_test_run": [
    {
      "command": "./run help",
      "what_it_does": "Lists the contributor command surface; run commands from the repository root unless stated otherwise.",
      "source_file": "README.md"
    },
    {
      "command": "./run bootstrap",
      "what_it_does": "Prints setup instructions and toolchain pins; works before Go is installed.",
      "source_file": "README.md"
    },
    {
      "command": "coop build",
      "what_it_does": "Builds the pinned development image; the recommended host setup requires Coop and Docker.",
      "source_file": "README.md"
    },
    {
      "command": "coop run -- ./run setup",
      "what_it_does": "Sets up sidecars, dependencies, migrations, and browser tooling through the Coop environment.",
      "source_file": "README.md"
    },
    {
      "command": "coop shell",
      "what_it_does": "Enters the development box.",
      "source_file": "README.md"
    },
    {
      "command": "asdf install",
      "what_it_does": "Installs the pinned native toolchains after the required asdf plugins are available.",
      "source_file": "run"
    },
    {
      "command": "./run setup",
      "what_it_does": "Validates prerequisites and prepares the local application and dependency services without seeding demo data.",
      "source_file": "portal/README.md"
    },
    {
      "command": "./run doctor",
      "what_it_does": "Reports installed prerequisite versions and actionable mismatches.",
      "source_file": "README.md"
    },
    {
      "command": "./run certs trust",
      "what_it_does": "Trusts the workspace development certificate on macOS; run once after setup.",
      "source_file": "portal/README.md"
    },
    {
      "command": "./run seed",
      "what_it_does": "Explicitly installs idempotent demo data, including the demo owner and runner enrollment key.",
      "source_file": "portal/README.md"
    },
    {
      "command": "./run serve",
      "what_it_does": "Starts Phoenix with live reload at the workspace URL.",
      "source_file": "README.md"
    },
    {
      "command": "./run urls",
      "what_it_does": "Prints workspace-specific Portal, metrics, PostgreSQL, and Keycloak URLs.",
      "source_file": "README.md"
    },
    {
      "command": "./run smoke",
      "what_it_does": "Starts the slower packaged Compose topology at localhost:4010.",
      "source_file": "README.md"
    },
    {
      "command": "./run check changed",
      "what_it_does": "Runs quick checks for changed files.",
      "source_file": "portal/README.md"
    },
    {
      "command": "./run test portal --stale",
      "what_it_does": "Runs stale Portal tests for focused feedback.",
      "source_file": "portal/README.md"
    },
    {
      "command": "./run test portal --failed",
      "what_it_does": "Reruns previously failed Portal tests.",
      "source_file": "portal/README.md"
    },
    {
      "command": "./run gate portal --changed",
      "what_it_does": "Checks changed Portal sources and runs affected application tests.",
      "source_file": "portal/AGENTS.md"
    },
    {
      "command": "./run gate portal",
      "what_it_does": "Runs the complete Portal compile, formatting, static analysis, security audits, tests, and test-output guard.",
      "source_file": "portal/AGENTS.md"
    },
    {
      "command": "(cd runner && go build -o ../bin/emisar .)",
      "what_it_does": "Builds the host runner and operator CLI.",
      "source_file": "runner/README.md"
    },
    {
      "command": "./run gate runner",
      "what_it_does": "Checks Go formatting, dependencies, static analysis, attestation parity, race tests, cross-builds, and installer behavior.",
      "source_file": "runner/AGENTS.md"
    },
    {
      "command": "(cd mcp && go build -o ../bin/emisar-mcp .)",
      "what_it_does": "Builds the local MCP bridge and direct CLI.",
      "source_file": "mcp/README.md"
    },
    {
      "command": "./run gate mcp",
      "what_it_does": "Checks Go quality, the standard-library-only dependency rule, attestation parity, tests, and supported-platform builds.",
      "source_file": "mcp/AGENTS.md"
    },
    {
      "command": "./run gate packs",
      "what_it_does": "Validates packs, hash goldens, the generated catalog, and focused Portal catalog tests; does not execute actions.",
      "source_file": "packs/AGENTS.md"
    },
    {
      "command": "./run test packs redis",
      "what_it_does": "Executes Redis pack behavior cases against disposable Compose services.",
      "source_file": "dev/README.md"
    },
    {
      "command": "./run test pack-access",
      "what_it_does": "Tests declared host-access grants and protected-resource behavior on disposable hosts.",
      "source_file": ".github/workflows/ci.yml"
    },
    {
      "command": "./run gate infra",
      "what_it_does": "Runs credential-free Terraform formatting, initialization, validation, TFLint, and cloud-init checks.",
      "source_file": "infra/README.md"
    },
    {
      "command": "./run gate tooling",
      "what_it_does": "Runs the required gate for executable contributor and agent tooling changes.",
      "source_file": "AGENTS.md"
    },
    {
      "command": "./run gate all",
      "what_it_does": "Runs the repository-wide verification gate.",
      "source_file": "AGENTS.md"
    },
    {
      "command": "./run check agent-setup",
      "what_it_does": "Checks contributor guidance, skill discovery, metadata, KB indexing, and hook policy.",
      "source_file": "AGENTS.md"
    },
    {
      "command": "./run check docs",
      "what_it_does": "Checks documentation; required alongside agent-setup for manuals, skills, or KB-only changes.",
      "source_file": "AGENTS.md"
    }
  ],
  "deploy_release": [
    {
      "step": "Pull requests to main run selected validation jobs under a read-only token; Required - CI combines their results into the required check.",
      "source_file": ".github/workflows/ci.yml"
    },
    {
      "step": "Each main push invokes CI from the same commit. CD loads and publishes the tested Portal image to GHCR by immutable digest, with provenance and the CI-produced SBOM.",
      "source_file": ".github/workflows/cd.yml"
    },
    {
      "step": "Pack changes or registry drift trigger serialized publication after CI. The publisher builds against the live catalog and writes immutable artifacts plus live registry pointers.",
      "source_file": "packs/PUBLISHING.md"
    },
    {
      "step": "CD creates a provisional HCP Terraform configuration and saved production plan using that commit's Portal image digest; required pack publication must finish first.",
      "source_file": ".github/workflows/cd.yml"
    },
    {
      "step": "Review the intended commit, resource changes, and image digest in HCP Terraform, then use Confirm & Apply. GitHub does not apply infrastructure.",
      "source_file": ".agent/kb/runbooks/deployment.md"
    },
    {
      "step": "The release entry point migrates before boot under Ecto's advisory lock. Verify rollout health, readiness, sign-in, runner reconnections, registry output, and cluster state.",
      "source_file": ".agent/kb/runbooks/deployment.md"
    },
    {
      "step": "Prepare a product release by updating portal/VERSION, the website changelog, license date, relevant tests, and catalog; run the required gates and certify Claude and Codex against the exact release commit.",
      "source_file": ".agent/kb/runbooks/release.md"
    },
    {
      "step": "Create and verify a signed annotated vMAJOR.MINOR.PATCH tag at the release anchor, push it, and publish matching GitHub release notes. Published release tags remain immutable.",
      "source_file": ".agent/kb/runbooks/release.md"
    },
    {
      "step": "Runner and MCP binaries use separate signed runner-vX.Y.Z and mcp-vX.Y.Z tags targeting current main. Update Portal compatibility versions and Compose pins before tagging; trusted workflows publish verified artifacts and GitHub mirrors.",
      "source_file": ".agent/kb/runbooks/deployment.md"
    },
    {
      "step": "The hosted MCP Registry listing is reconciled from protected main by schedule or manual dispatch and follows the live deployed product version rather than the product tag alone.",
      "source_file": ".github/workflows/mcp-registry-release.yml"
    },
    {
      "step": "Rollback uses another reviewed saved plan selecting a previous immutable image digest. Database changes are not reversed, so confirm that the older image supports the current schema.",
      "source_file": ".agent/kb/runbooks/deployment.md"
    }
  ],
  "conventions": [
    {
      "rule": "Read the root and touched project's AGENTS.md plus relevant KB rules before editing; CLAUDE.md and GEMINI.md point to the canonical manual.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Keep changes focused, reuse existing shapes, and avoid speculative abstractions or unnecessary dependencies.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Validate untrusted input and preserve authorization, account isolation, pack trust, audit, redaction, and denial coverage.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Use ./run for contributor checks and finish with the relevant project gate; distinguish local validation from publication and live verification.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Preserve unrelated work, stage only owned changes, use the current checkout, and allow only one agent to write, gate, or commit at a time.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Claim implementation work through Coop; completion includes green gates, a focused commit with a Coop-Task trailer, updated task records, and closing the task.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Coop-box gates stay Docker-free; Docker-backed integration work belongs in an environment with the required host services.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Portal contexts own authorization: check Subject permissions before database access and scope queries to the subject immediately before fetching.",
      "source_file": "portal/AGENTS.md"
    },
    {
      "rule": "Keep queries in Query modules, schemas limited to data shape, changesets pure, and public context returns tagged.",
      "source_file": "portal/AGENTS.md"
    },
    {
      "rule": "Authorize every LiveView event and MCP/controller action; changed context behavior needs happy-path, denial, and cross-account tests.",
      "source_file": "portal/AGENTS.md"
    },
    {
      "rule": "Never edit or delete production-applied migrations; add a new migration. Run the complete Portal gate before pushing or releasing.",
      "source_file": "portal/AGENTS.md"
    },
    {
      "rule": "Go code uses contextual error wrapping, slog, standard-library table-driven tests, and minimal dependencies; maintainer tooling belongs in tools.",
      "source_file": "runner/AGENTS.md"
    },
    {
      "rule": "The runner revalidates arguments and pack hashes, contains paths, redacts output before transmission, and requires regression tests for security decisions.",
      "source_file": "runner/AGENTS.md"
    },
    {
      "rule": "Keep MCP tool behavior and catalogs server-owned; preserve the bridge's standard-library-only boundary and byte-identical attestation implementations in MCP and runner.",
      "source_file": "mcp/AGENTS.md"
    },
    {
      "rule": "Pack changes need behavior tests as well as validation, appropriate version bumps, and regenerated catalog artifacts in the same commit.",
      "source_file": "packs/AGENTS.md"
    },
    {
      "rule": "Pack shell programs are authored and fixed; bound inputs, declare helper binaries, contain file paths, and assign risk from actual impact.",
      "source_file": "packs/AGENTS.md"
    },
    {
      "rule": "Infrastructure stays private by default with least-privilege IAM and protected stateful resources; secret values enter through sensitive HCP workspace variables.",
      "source_file": "infra/AGENTS.md"
    },
    {
      "rule": "Open an issue for significant changes, keep PRs small, explain tradeoffs, and update tests and documentation for behavior changes.",
      "source_file": ".github/CONTRIBUTING.md"
    },
    {
      "rule": "Respect the Apache versus BSL licensing split and any required CLA; review AI-assisted work and disclose material assistance when requested.",
      "source_file": ".github/CONTRIBUTING.md"
    },
    {
      "rule": "Do not include secrets or confidential material in contributions, and report vulnerabilities through the security process rather than public issues.",
      "source_file": ".github/CONTRIBUTING.md"
    }
  ],
